const regex = new RegExp(slowo, "i");
console.log(regex.test("Lubie Programowanie w JavaScript")); // true

const regex = /^\d{3,5}$/;
console.log(regex.test("1234")); // true
console.log(regex.test("12")); // false

const regex = /\d+/gi;
console.log(regex.source); // "\d+"
console.log(regex.flags); // "gi"

const tekst = "a1b2c3";
const wynik = tekst.replace(/\d/g, (cyfra) => "[" + cyfra + "]");
console.log(wynik); // "a[1]b[2]c[3]"

const regex = /a/g;
const tekst = "aaa";
console.log(regex.test(tekst)); // true
console.log(regex.test(tekst)); // true
console.log(regex.lastIndex); // 2

const tekst = "a1 b22 c333";
const dopasowania = [...tekst.matchAll(/\d+/g)];
console.log(dopasowania.length); // 3

const numer = "1234567890123456";
const zamaskowany = numer.replace(/\d(?=\d{4})/g, "*");
console.log(zamaskowany); // "************3456"

